?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Case Builder | TechSelectAI</title><meta name="robots" content="noindex,nofollow"><link rel="icon" href="/favicon.svg"><style>body{margin:0;font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#172033}.top{background:#fff;border-bottom:1px solid #e2e8f0;padding:15px max(20px,5vw)}.top img{height:34px}.wrap{max-width:980px;margin:30px auto;padding:0 20px 60px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:700;margin:10px 0 6px}input,textarea{width:100%;box-sizing:border-box;padding:11px 12px;border:1px solid #cbd5e1;border-radius:10px;font:inherit}textarea{min-height:96px;resize:vertical}button{padding:11px 16px;border:0;border-radius:10px;background:#1A365D;color:#fff;font-weight:700;cursor:pointer}.muted{color:#64748b}.notice{padding:12px 14px;background:#eef8f7;border-radius:10px}.section{border-top:1px solid #e2e8f0;padding-top:14px;margin-top:14px}.facts{background:#f8fbfd}.tag{font-size:12px;font-weight:800;text-transform:uppercase;color:#319795;letter-spacing:.05em}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions a{padding:10px 13px;border:1px solid #cbd5e1;border-radius:10px;text-decoration:none;color:#1A365D;background:#fff;font-weight:700}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><a href="/"><img src="/techselectai-logo.svg" alt="TechSelectAI"></a></header><main class="wrap"><div class="actions"><a href="/my-business-cases">My Business Cases</a><a href="/my-consultations">My Consultations</a></div><h1>Business Case Builder</h1><p class="muted">Turn a TechSelectAI product recommendation into a management-ready justification. Verified product facts remain separate from your assumptions and AI-generated estimates.</p><div id="app" class="card">Loading…</div></main><script>
const app=document.getElementById('app'),id=Number(new URLSearchParams(location.search).get('id')||0);let csrf='',data=null;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function req(url,opt={}){const r=await fetch(url,opt),d=await r.json();if(!r.ok)throw new Error(d.message||d.error||'Request failed');return d}function fields(a={}){const defs=[['current_situation','Current situation / process'],['current_solution','Current solution'],['pain_points','Pain points'],['expected_benefits','Expected benefits'],['stakeholders','Key stakeholders'],['implementation_timeline','Implementation timeline'],['budget_assumptions','Budget / cost assumptions'],['roi_assumptions','ROI assumptions'],['risks','Known risks or concerns']];return defs.map(([k,l])=>`<label for="${k}">${l}</label><textarea id="${k}">${esc(a[k]||'')}</textarea>`).join('')}function renderOutput(o){if(!o)return '<p class="muted">No generated business case yet.</p>';const keys=['executive_summary','current_situation','objectives','why_this_product','requirement_fit','expected_benefits','financial_roi_assumptions','implementation_approach','risks_mitigations','alternatives_considered','recommendation','next_steps'];return keys.map(k=>o[k]?`<div class="section"><h3>${esc(o[k].title)}</h3><p>${esc(o[k].content).replace(/\n/g,'<br>')}</p></div>`:'').join('')+`<div class="section facts"><div class="tag">Verified facts used</div><ul>${(o.verified_facts_used||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="tag">User assumptions / estimates</div><ul>${(o.assumptions_used||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="tag">Caveats</div><ul>${(o.caveats||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`}function collect(){const a={};['current_situation','current_solution','pain_points','expected_benefits','stakeholders','implementation_timeline','budget_assumptions','roi_assumptions','risks'].forEach(k=>a[k]=document.getElementById(k)?.value.trim()||'');return a}async function load(){if(!id){app.innerHTML='<div class="notice">Open a saved business case from My Business Cases, or start one from a product recommendation.</div>';return}try{const auth=await req('/api/auth/csrf');csrf=auth.csrf_token||'';const d=await req('/api/business-cases/'+id);data=d.business_case;const facts=data.verified_facts_json||{};app.innerHTML=`<label for="title">Business case title</label><input id="title" value="${esc(data.title)}"><div class="grid"><div><h2>Your assumptions</h2><p class="muted">These are treated as user-provided assumptions, not vendor facts.</p>${fields(data.assumptions_json||{})}</div><div><h2>Verified context</h2><div class="facts card"><p><b>Product:</b> ${esc(facts.product?.name||data.product_name)}</p><p><b>Vendor:</b> ${esc(facts.product?.vendor||'Not recorded')}</p><p><b>Category:</b> ${esc(facts.product?.category||'Not recorded')}</p>${facts.consultation?.business_problem?`<p><b>Business problem:</b> ${esc(facts.consultation.business_problem)}</p>`:''}<p class="muted">Only stored TechSelectAI facts are treated as verified input to the generator.</p></div></div></div><div class="actions"><button id="save">Save assumptions</button><button id="generate">${data.generated_output_json?'Regenerate':'Generate business case'}</button></div><p id="msg" class="muted"></p><h2>Generated business case</h2><div id="output">${renderOutput(data.generated_output_json)}</div>`;document.getElementById('save').onclick=save;document.getElementById('generate').onclick=generate}catch(e){app.innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}async function save(){const m=document.getElementById('msg');m.textContent='Saving…';try{await req('/api/business-cases/'+id,{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({title:document.getElementById('title').value,assumptions:collect()})});m.textContent='Saved.'}catch(e){m.textContent=e.message}}async function generate(){const m=document.getElementById('msg'),b=document.getElementById('generate');b.disabled=true;m.textContent='Saving assumptions and generating…';try{await req('/api/business-cases/'+id,{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({title:document.getElementById('title').value,assumptions:collect()})});const d=await req('/api/business-cases/'+id+'/generate',{method:'POST',headers:{'X-CSRF-Token':csrf}});document.getElementById('output').innerHTML=renderOutput(d.output);m.textContent='Business case generated and saved.'}catch(e){m.textContent=e.message}finally{b.disabled=false}}load();
</script></body></html>